package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.portal.kernel.model.User;
import it.servizidigitali.common.fdr.service.FirmaRemotaService;
import it.servizidigitali.common.utility.enumeration.Contesto;
import it.servizidigitali.common.utility.exception.FirmaDigitaleRemotaException;
import it.servizidigitali.gestione.referente.istanze.common.dto.DatiPraticaDTO;
import it.servizidigitali.gestione.referente.istanze.common.dto.OtpCredentialsDTO;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

@Component(immediate = true, service = PdfSigningProcessor.class)
public class PdfSigningProcessor {

    @Reference
    private FirmaRemotaService firmaRemotaService;

    public byte[] applyDigitalSignature(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            OtpCredentialsDTO otpCredentialsDTO,
            DatiPraticaDTO datiPraticaDTO) {

        if (otpCredentialsDTO.isCredentialsNotPresent()) {
            return pdfBuffer;
        }

        try {
            long groupId = richiestaReferenteIstanza.getGroupId();
            long userId = operatore.getUserId();
            Contesto contesto = datiPraticaDTO.getContesto();

            return firmaRemotaService.applicaSigillo(
                    groupId,
                    userId,
                    contesto,
                    pdfBuffer,
                    otpCredentialsDTO.getCodiceOtpFirma(),
                    otpCredentialsDTO.getPassword());
        } catch (FirmaDigitaleRemotaException e) {
            throw new FirmaDigitaleRemotaException();
        }
    }

    public byte[] applyElectronicSeal(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            DatiPraticaDTO datiPraticaDTO) {

        try {
            long groupId = richiestaReferenteIstanza.getGroupId();
            Contesto contesto = datiPraticaDTO.getContesto();
            return firmaRemotaService.applicaSigillo(groupId, 0, contesto, pdfBuffer, null, null);
        } catch (FirmaDigitaleRemotaException e) {
            throw new FirmaDigitaleRemotaException();
        }
    }
}

package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.portal.kernel.model.User;
import it.servizidigitali.common.fdr.dto.VerificaResponse;
import it.servizidigitali.file.utility.service.PdfService;
import it.servizidigitali.gestione.referente.istanze.common.builder.DocumentFileDescriptorBuilder;
import it.servizidigitali.gestione.referente.istanze.common.dto.DatiPraticaDTO;
import it.servizidigitali.gestione.referente.istanze.common.dto.OtpCredentialsDTO;
import it.servizidigitali.gestione.referente.istanze.common.dto.RichiestaDTO;
import it.servizidigitali.gestione.referente.istanze.common.enumeration.EsitoLavorazione;
import it.servizidigitali.gestione.referente.istanze.common.pojo.DocumentFileDescriptor;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import java.util.Date;
import java.util.Objects;

@Component(immediate = true, service = ReferentChangePdfOrchestrator.class)
public class ReferentChangePdfOrchestrator {

    @Reference
    private PdfService pdfServiceUtil;

    @Reference
    private ReferentRequestAttachmentCreationProcessor referentRequestAttachmentCreationProcessor;

    @Reference
    private PdfFingerprintProcessor pdfFingerprintProcessor;

    @Reference
    private ProtocolRegistrationProcessor protocolRegistrationProcessor;

    @Reference
    private PdfGenerationProcessor pdfGenerationProcessor;

    @Reference
    private PdfSigningProcessor pdfSigningProcessor;

    @Reference
    private DocumentRepositoryStorageProcessor documentRepositoryStorageProcessor;

    public void processPdf(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            Date dataEsito,
            EsitoLavorazione esitoLavorazione,
            OtpCredentialsDTO otpCredentialsDTO,
            DatiPraticaDTO datiPraticaDTO,
            RichiestaDTO richiestaDTO) {

        processPdf(richiestaReferenteIstanza, operatore, dataEsito, esitoLavorazione, otpCredentialsDTO, datiPraticaDTO, richiestaDTO, false);
    }

    public void processPdf(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            Date dataEsito,
            EsitoLavorazione esitoLavorazione,
            OtpCredentialsDTO otpCredentialsDTO,
            DatiPraticaDTO datiPraticaDTO,
            RichiestaDTO richiestaDTO,
            boolean approvazioneAutomatica) {

        Objects.requireNonNull(richiestaReferenteIstanza, "richiestaReferenteIstanza must not be null");
        Objects.requireNonNull(operatore, "operatore must not be null");
        Objects.requireNonNull(dataEsito, "dataEsito must not be null");
        Objects.requireNonNull(esitoLavorazione, "esitoLavorazione must not be null");
        Objects.requireNonNull(otpCredentialsDTO, "otpCredentialsDTO must not be null");
        Objects.requireNonNull(datiPraticaDTO, "datiPraticaDTO must not be null");

        byte[] finalPdfBuffer = preparePdf(richiestaReferenteIstanza,
                operatore,
                dataEsito,
                esitoLavorazione,
                otpCredentialsDTO,
                datiPraticaDTO,
                richiestaDTO,
                approvazioneAutomatica);

        DocumentFileDescriptor documentFileDescriptor = buildDocumentFileDescriptor(
                        richiestaReferenteIstanza,
                        operatore,
                        esitoLavorazione,
                        datiPraticaDTO);

        VerificaResponse verificationResponse = retrieveFingerprint(
                finalPdfBuffer,
                richiestaReferenteIstanza,
                datiPraticaDTO,
                documentFileDescriptor,
                otpCredentialsDTO);

        storeAndRegisterDocument(
                finalPdfBuffer,
                richiestaReferenteIstanza,
                operatore,
                datiPraticaDTO,
                documentFileDescriptor,
                verificationResponse);
    }

    private byte[] preparePdf(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            Date dataEsito,
            EsitoLavorazione esitoLavorazione,
            OtpCredentialsDTO otpCredentialsDTO,
            DatiPraticaDTO datiPraticaDTO,
            RichiestaDTO richiestaDTO,
            boolean approvazioneAutomatica) {

        byte[] pdfBuffer = pdfGenerationProcessor.generatePdf(
                richiestaReferenteIstanza,
                operatore,
                dataEsito,
                esitoLavorazione,
                richiestaDTO,
                approvazioneAutomatica);

        pdfBuffer = pdfServiceUtil.generaPDFArchive(pdfBuffer);

        pdfBuffer = pdfSigningProcessor.applyDigitalSignature(
                pdfBuffer,
                richiestaReferenteIstanza,
                operatore,
                otpCredentialsDTO,
                datiPraticaDTO);

        return pdfSigningProcessor.applyElectronicSeal(
                pdfBuffer,
                richiestaReferenteIstanza,
                datiPraticaDTO);
    }

    private DocumentFileDescriptor buildDocumentFileDescriptor(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            EsitoLavorazione esitoLavorazione,
            DatiPraticaDTO datiPraticaDTO) {

        return DocumentFileDescriptorBuilder.build(
                richiestaReferenteIstanza,
                operatore,
                esitoLavorazione,
                datiPraticaDTO);
    }

    private VerificaResponse retrieveFingerprint(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            DatiPraticaDTO datiPraticaDTO,
            DocumentFileDescriptor documentFileDescriptor,
            OtpCredentialsDTO otpCredentialsDTO) {

        boolean digitalSignatureApplied = otpCredentialsDTO.isCredentialsPresent();

        return pdfFingerprintProcessor.retrieveFingerprint(
                pdfBuffer,
                richiestaReferenteIstanza,
                datiPraticaDTO,
                documentFileDescriptor,
                digitalSignatureApplied);
    }

    private void storeAndRegisterDocument(
            byte[] pdfBuffer,
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            DatiPraticaDTO datiPraticaDTO,
            DocumentFileDescriptor documentFileDescriptor,
            VerificaResponse verificationResponse) {

        String documentRepositoryKeyId = documentRepositoryStorageProcessor.saveToDocumentRepository(
                pdfBuffer,
                documentFileDescriptor);

        long allegatoReferenteIstanzaId = referentRequestAttachmentCreationProcessor.execute(
                richiestaReferenteIstanza,
                operatore,
                documentRepositoryKeyId,
                documentFileDescriptor,
                verificationResponse);

        protocolRegistrationProcessor.registerProtocol(
                richiestaReferenteIstanza,
                documentRepositoryKeyId,
                allegatoReferenteIstanzaId,
                datiPraticaDTO,
                documentFileDescriptor);
    }
}

