package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import it.servizidigitali.common.utility.exception.DataAccessException;
import it.servizidigitali.file.utility.factory.FileServiceFactory;
import it.servizidigitali.file.utility.model.File;
import it.servizidigitali.gestione.referente.istanze.common.pojo.DocumentFileDescriptor;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import java.io.ByteArrayInputStream;
import java.io.InputStream;

@Component(immediate = true, service = DocumentRepositoryStorageProcessor.class)
public class DocumentRepositoryStorageProcessor {

    private static final Log log = LogFactoryUtil.getLog(DocumentRepositoryStorageProcessor.class.getName());

    @Reference
    private FileServiceFactory fileServiceFactory;

    public String saveToDocumentRepository(byte[] pdfBuffer, DocumentFileDescriptor documentFileDescriptor) {
        try (InputStream inputStream = new ByteArrayInputStream(pdfBuffer)) {
            File savedFile = fileServiceFactory.getActiveFileService()
                    .saveRequestFile(
                            documentFileDescriptor.getFileName(),
                            documentFileDescriptor.getTitle(),
                            documentFileDescriptor.getDescription(),
                            documentFileDescriptor.getPracticeCode(),
                            documentFileDescriptor.getRequestId(),
                            inputStream,
                            documentFileDescriptor.getMimeType(),
                            documentFileDescriptor.getUserId(),
                            documentFileDescriptor.getGroupId());

            return savedFile.getId();
        } catch (Exception e) {
            log.error("Errore durante il salvataggio del file", e);
            throw new DataAccessException();
        }
    }
}

