package it.servizidigitali.gestione.referente.istanze.common.builder;

import com.liferay.portal.kernel.model.User;
import com.liferay.portal.kernel.util.MimeTypesUtil;
import it.servizidigitali.gestione.referente.istanze.common.dto.DatiPraticaDTO;
import it.servizidigitali.gestione.referente.istanze.common.enumeration.EsitoLavorazione;
import it.servizidigitali.gestione.referente.istanze.common.pojo.DocumentFileDescriptor;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;

public class DocumentFileDescriptorBuilder {
    public static DocumentFileDescriptor build(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            User operatore,
            EsitoLavorazione esitoLavorazione,
            DatiPraticaDTO datiPraticaDTO) {

        long richiestaReferenteIstanzaId = richiestaReferenteIstanza.getRichiestaReferenteIstanzaId();
        String title = richiestaReferenteIstanzaId + "-esito-richiesta-cambio-referente";
        String fileName = title + ".pdf";

        String description = "Esito richiesta cambio referente, richiestaReferenteIstanzaId: " + richiestaReferenteIstanzaId;

        String mimeType = MimeTypesUtil.getContentType(fileName);

        return new DocumentFileDescriptor(
                fileName,
                title,
                description,
                mimeType,
                datiPraticaDTO.getCodice(),
                richiestaReferenteIstanza.getRichiestaId(),
                operatore.getUserId(),
                richiestaReferenteIstanza.getGroupId());
    }
}

