83		@Override
84		public File saveRequestFile(String nomeFile, String titolo, String descrizione, String codiceServizio,
85				long richiestaId, InputStream inputStream, String mimeType, long userId, long groupId)
86				throws FileServiceException {
87	
88			File savedFile = null;
89			try {
90	
91				Session session = SessionFactoryImpl.newInstance().getRepositories(parameters).get(0).createSession();
92	
93				Organization organization = organizationUtility.getSiteOrganization(groupId);
94	
95				User user = userLocalService.getUser(userId);
96	
97				Folder rootFolder = getRootFolder(organization, session);
98				// get/creazione folder utente
99				Folder userFolder = getOrCreateFolder(user.getScreenName(), rootFolder, session);
100	
101				// get/creazione folder "public"
102				Folder publicUserFolder = getOrCreateFolder(PUBLIC_FOLDER_NAME, userFolder, session);
103	
104				// get/creazione folder "codiceServizio"
105				Folder codiceServizioFolder = getOrCreateFolder(codiceServizio, publicUserFolder, session);
106	
107				Folder richiestaIdFolder = getOrCreateFolder(String.valueOf(richiestaId), codiceServizioFolder, session);
108	
109				// Generazione file univoco per folder di destinazione (per evitare
110				// sovrascritture)
111				nomeFile = getUniqueFileName(richiestaIdFolder, nomeFile);
112	
113				// Salvataggio documento in folder
114				byte[] bytes = inputStream.readAllBytes();
115				ByteArrayInputStream stream = new ByteArrayInputStream(bytes);
116				ContentStream contentStream = session.getObjectFactory().createContentStream(nomeFile, bytes.length,
117						mimeType, stream);
118	
119				// Update
120				Document document = null;
121				try {
122					document = (Document) session.getObjectByPath(richiestaIdFolder.getPath() + "/" + nomeFile);
123				} catch (CmisObjectNotFoundException e) {
124					// log neutro: il messaggio nativo conterrebbe il path Alfresco completo, che include
125					// lo screenName dell'utente (= codice fiscale per utenti SPID) come componente di
126					// directory. Si logga solo userId/richiestaId/nomeFile per diagnosi senza esporre PII.
127					log.warn("saveRequestFile :: oggetto non esistente per userId=" + userId
128							+ " richiestaId=" + richiestaId + " nomeFile=" + nomeFile);
129				}
130				if (document != null) {
131					document.setContentStream(contentStream, true);
132				}
133				// Create
134				else {
135					// properties
136					Map<String, Object> properties = new HashMap<String, Object>();
137					properties.put(PropertyIds.OBJECT_TYPE_ID, "cmis:document");
138					properties.put(PropertyIds.NAME, nomeFile);
139					properties.put(PropertyIds.DESCRIPTION, titolo);
140					document = richiestaIdFolder.createDocument(properties, contentStream, VersioningState.MAJOR);
141					// TODO Verificare
142					//properties.put("cm:title", titolo);
143					//document.updateProperties(properties);
144	
145				}
146				log.debug("saveRequestFile :: file '" + document.getName() + "' creato correttamente ");
147	
148	
149				savedFile = new File();
150				savedFile.setId(document.getId());
151				savedFile.setNome(nomeFile);
152				savedFile.setMimeType(mimeType);
153				savedFile.setTitolo(titolo);
154				savedFile.setDescrizione(descrizione);
155				savedFile.setInputStream(contentStream.getStream());
156	
157				BigInteger size = document.<BigInteger>getPropertyValue(PropertyIds.CONTENT_STREAM_LENGTH);
158				if (Validator.isNotNull(size)) {
159					savedFile.setSize(size.longValue());
160				}
161	
162				return savedFile;
163			} catch (Exception e) {
164				log.error("saveRequestFile :: " + e.getMessage(), e);
165				throw new FileServiceException(e);
166			}
167		}
