169		/**
170		 *
171		 * @param folder
172		 * @param fileName
173		 * @return
174		 * @throws PortalException
175		 */
176		public String getUniqueFileName(Folder folder, String fileName) throws PortalException {
177	
178			boolean found = existsFileIntoFolder(folder, fileName);
179	
180			if (!found) {
181				return fileName;
182			}
183	
184			String fileNameWithOutExt = FilenameUtils.removeExtension(fileName);
185			String extension = FilenameUtils.getExtension(fileName);
186			int lastIncremental = 1;
187	
188			if (Character.isDigit(fileNameWithOutExt.charAt(fileNameWithOutExt.length() - 1))) {
189				lastIncremental = Integer.parseInt(fileNameWithOutExt.substring(fileNameWithOutExt.length() - 1));
190				lastIncremental++;
191				fileNameWithOutExt = fileNameWithOutExt.substring(0, fileNameWithOutExt.length() - 1);
192			}
193			fileName = fileNameWithOutExt + lastIncremental + "." + extension;
194	
195			// nuovo test esistenza
196			found = existsFileIntoFolder(folder, fileName);
197			if (found) {
198				fileName = getUniqueFileName(folder, fileName);
199			}
200	
201			return fileName;
202		}
