204		/**
205		 *
206		 * @param folder
207		 * @param fileName
208		 * @return
209		 * @throws PortalException
210		 */
211		private boolean existsFileIntoFolder(Folder folder, String fileName) throws PortalException {
212	
213			boolean found = false;
214			for (CmisObject child : folder.getChildren()) {
215				if (child instanceof Document) {
216					Document childDoument = (Document) child;
217					if (childDoument.getName().equals(fileName)) {
218						found = true;
219						break;
220					}
221				}
222	
223			}
224	
225			return found;
226		}
