267		public List<File> getUserFolderFiles(long userId, long groupId) throws FileServiceException {
268	
269			try {
270				Session session = SessionFactoryImpl.newInstance().getRepositories(parameters).get(0).createSession();
271	
272				Organization organization = organizationUtility.getSiteOrganization(groupId);
273	
274				Folder rootFolder = getRootFolder(organization, session);
275	
276				User user = userLocalService.getUser(userId);
277	
278				// get/creazione folder utente
279				Folder userFolder = getFolder(user.getScreenName(), rootFolder, session);
280				if (userFolder == null) {
281					return null;
282				}
283	
284				// get/creazione folder "public"
285				Folder privateUserFolder = getOrCreateFolder(PRIVATE_FOLDER_NAME, userFolder, session);
286	
287				if (privateUserFolder == null) {
288					return null;
289				}
290	
291				// get/creazione folder "private"
292				List<File> result = new ArrayList<File>();
293				for (CmisObject child : privateUserFolder.getChildren()) {
294					if (child instanceof Document) {
295						Document childDoument = (Document) child;
296						File file = getFile(childDoument);
297						result.add(file);
298					}
299	
300				}
301				return result;
302			} catch (Exception e) {
