342				folderPath = rootFolder.getPath() + folderName;
343			} else {
344				folderPath = rootFolder.getPath() + "/" + folderName;
345			}
346			try {
347				folder = (Folder) session.getObjectByPath(folderPath);
348			} catch (CmisObjectNotFoundException e) {
349				log.warn("la cartella '" + folderPath + "' non esiste :: " + e.getMessage());
350			}
351			return folder;
352		}
