355	
356			Folder folder = null;
357			String folderPath = null;
358			if (rootFolder.isRootFolder()) {
359				folderPath = rootFolder.getPath() + folderName;
360			} else {
361				folderPath = rootFolder.getPath() + "/" + folderName;
362			}
363			try {
364				folder = (Folder) session.getObjectByPath(folderPath);
365			} catch (CmisObjectNotFoundException e) {
366				log.warn("la cartella '" + folderPath + "' non esiste :: " + e.getMessage());
367				Map<String, Object> props = new HashMap<>();
368				props.put("cmis:objectTypeId", "cmis:folder");
369				props.put("cmis:name", folderName);
370				log.info("creazione cartella '" + folderPath + "'");
371				folder = rootFolder.createFolder(props);
372			}
373			return folder;
374		}
