376		@Override
377		public File updateRequestFile(String nomeFile, String titolo, String descrizione, String codiceServizio,
378				long richiestaId, InputStream inputStream, String mimeType, long userId, long groupId, String idDocumentale)
379				throws FileServiceException {
380			File savedFile = null;
381			try {
382	
383				Session session = SessionFactoryImpl.newInstance().getRepositories(parameters).get(0).createSession();
384	
385				Organization organization = organizationUtility.getSiteOrganization(groupId);
386	
387				User user = userLocalService.getUser(userId);
388	
389				Folder rootFolder = getRootFolder(organization, session);
390				// get/creazione folder utente
391				Folder userFolder = getOrCreateFolder(user.getScreenName(), rootFolder, session);
392	
393				// get/creazione folder "public"
394				Folder publicUserFolder = getOrCreateFolder(PUBLIC_FOLDER_NAME, userFolder, session);
395	
396				// get/creazione folder "codiceServizio"
397				Folder codiceServizioFolder = getOrCreateFolder(codiceServizio, publicUserFolder, session);
398	
399				Folder richiestaIdFolder = getOrCreateFolder(String.valueOf(richiestaId), codiceServizioFolder, session);
400	
401				// Generazione file univoco per folder di destinazione (per evitare
402				// sovrascritture)
403				nomeFile = getUniqueFileName(richiestaIdFolder, nomeFile);
404	
405				// Update
406				savedFile = new File();
407				Document document = null;
408				try {
409					// document = (Document) session.getObjectByPath(richiestaIdFolder.getPath() +
410					// "/" + nomeFile);
411					document = (Document) session.getObject(idDocumentale);
412				} catch (CmisObjectNotFoundException e) {
413					log.warn("saveRequestFile :: " + e.getMessage());
414				}
415	
416				Map<String, Object> properties = new HashMap<String, Object>();
417				if (Validator.isNotNull(inputStream)) {
418					// Salvataggio documento in folder
419					byte[] bytes = inputStream.readAllBytes();
420					ByteArrayInputStream stream = new ByteArrayInputStream(bytes);
421					ContentStream contentStream = session.getObjectFactory().createContentStream(nomeFile, bytes.length,
422							mimeType, stream);
423	
424					if (document.getAllowableActions().getAllowableActions()
425							.contains(org.apache.chemistry.opencmis.commons.enums.Action.CAN_CHECK_OUT)) {
426						document.refresh();
427						ObjectId idOfCheckedOutDocument = document.checkOut();
428						Document pwc = (Document) session.getObject(idOfCheckedOutDocument);
429	
430						properties.put(PropertyIds.OBJECT_TYPE_ID, "cmis:document");
431						properties.put(PropertyIds.NAME, nomeFile);
432						properties.put(PropertyIds.DESCRIPTION, titolo);
433	
434						ObjectId objectId = pwc.checkIn(false, properties, contentStream, null);
435						document = (Document) session.getObject(objectId);
436	
437						log.info("Version label is now:" + document.getVersionLabel());
438	
439						savedFile.setId(document.getId());
440						savedFile.setNome(nomeFile);
441						savedFile.setMimeType(mimeType);
442						savedFile.setTitolo(titolo);
443						savedFile.setDescrizione(descrizione);
444						savedFile.setInputStream(contentStream.getStream());
445	
446						BigInteger size = document.<BigInteger>getPropertyValue(PropertyIds.CONTENT_STREAM_LENGTH);
447						if (Validator.isNotNull(size)) {
448							savedFile.setSize(size.longValue());
449						}
450					} else {
451						log.error("Impossibile aggiornare il documento con id: " + idDocumentale);
