package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.counter.kernel.service.CounterLocalService;
import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.model.User;
import it.servizidigitali.common.fdr.dto.VerificaResponse;
import it.servizidigitali.common.utility.enumeration.EsitoVerificaFirma;
import it.servizidigitali.gestione.referente.istanze.common.pojo.DocumentFileDescriptor;
import it.servizidigitali.gestione.referente.istanze.model.AllegatoReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.service.AllegatoReferenteIstanzaLocalService;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

@Component(immediate = true, service = ReferentRequestAttachmentCreationProcessor.class)
public class ReferentRequestAttachmentCreationProcessor {

    private static final Log _log = LogFactoryUtil.getLog(ReferentRequestAttachmentCreationProcessor.class);

    @Reference
    private CounterLocalService counterLocalService;

    @Reference
    private AllegatoReferenteIstanzaLocalService allegatoReferenteIstanzaLocalService;

    public long execute(RichiestaReferenteIstanza richiestaReferenteIstanza, User operatore, String documentRepositoryKeyId, DocumentFileDescriptor documentFileDescriptor, VerificaResponse verificationResponse) {
        _log.info("add new file");

        long allegatoReferenteId = counterLocalService.increment(AllegatoReferenteIstanza.class.getName());
        AllegatoReferenteIstanza allegatoModel = allegatoReferenteIstanzaLocalService.createAllegatoReferenteIstanza(allegatoReferenteId);

        allegatoModel.setGroupId(richiestaReferenteIstanza.getGroupId());
        allegatoModel.setCompanyId(richiestaReferenteIstanza.getCompanyId());
        allegatoModel.setUserId(operatore.getUserId());
        allegatoModel.setUserName(operatore.getFullName());
        allegatoModel.setRichiestaReferenteIstanzaId(richiestaReferenteIstanza.getRichiestaReferenteIstanzaId());

        allegatoModel.setNome(documentFileDescriptor.getFileName());
        allegatoModel.setTitolo(documentFileDescriptor.getTitle());
        allegatoModel.setDescrizione(documentFileDescriptor.getDescription());
        allegatoModel.setPrincipale(false);
        allegatoModel.setInterno(true);

        allegatoModel.setIdDocumentale(documentRepositoryKeyId);

        allegatoModel.setEsitoVerificaFirma(EsitoVerificaFirma.OK.name());

        boolean firmatiDigitalmente = verificationResponse != null && verificationResponse.isFirmato();
        allegatoModel.setFirmatoDigitalmente(firmatiDigitalmente);

        String firmatari = "";
        if (firmatiDigitalmente) {
            _log.info("\tfirmato digitalmente");
            firmatari = operatore.getFullName();
        }

        allegatoModel.setFirmatario(firmatari);

        String impronta = verificationResponse != null ? verificationResponse.getImpronta() : null;
        allegatoModel.setImpronta(impronta);

        allegatoReferenteIstanzaLocalService.updateAllegatoReferenteIstanza(allegatoModel);

        return allegatoReferenteId;
    }
