package it.servizidigitali.gestione.referente.istanze.common.referentchangepdf;

import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.util.Validator;
import it.servizidigitali.common.utility.exception.KosmosException;
import it.servizidigitali.file.utility.factory.FileServiceFactory;
import it.servizidigitali.gestione.referente.istanze.common.builder.ProtocolloRequestBuilder;
import it.servizidigitali.gestione.referente.istanze.common.dto.DatiPraticaDTO;
import it.servizidigitali.gestione.referente.istanze.common.pojo.DocumentFileDescriptor;
import it.servizidigitali.gestione.referente.istanze.model.RichiestaReferenteIstanza;
import it.servizidigitali.gestione.referente.istanze.service.AllegatoReferenteIstanzaLocalService;
import it.servizidigitali.gestione.referente.istanze.service.RichiestaReferenteIstanzaLocalService;
import it.servizidigitali.protocollo.integration.model.ProtocolloRequest;
import it.servizidigitali.protocollo.integration.model.ProtocolloResponse;
import it.servizidigitali.protocollo.integration.service.ProtocolloService;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

@Component(immediate = true, service = ProtocolRegistrationProcessor.class)
public class ProtocolRegistrationProcessor {
    private static final Log _log = LogFactoryUtil.getLog(ProtocolRegistrationProcessor.class);

    @Reference
    private ProtocolloService protocolloService;

    @Reference
    private RichiestaReferenteIstanzaLocalService richiestaReferenteIstanzaLocalService;

    @Reference
    private AllegatoReferenteIstanzaLocalService allegatoReferenteIstanzaLocalService;

    @Reference
    private FileServiceFactory fileServiceFactory;

    @Reference
    private ProtocolloRequestBuilder protocolloRequestBuilder;

    public void registerProtocol(
            RichiestaReferenteIstanza richiestaReferenteIstanza,
            String documentRepositoryKeyId,
            long allegatoReferenteIstanzaId,
            DatiPraticaDTO datiPraticaDTO,
            DocumentFileDescriptor documentFileDescriptor) {
        _log.info("registerProtocol");

        ProtocolloRequest request = protocolloRequestBuilder.build(
                richiestaReferenteIstanza,
                datiPraticaDTO,
                documentRepositoryKeyId,
                documentFileDescriptor);

        long groupId = richiestaReferenteIstanza.getGroupId();
        long richiestaReferenteIstanzaId = richiestaReferenteIstanza.getRichiestaReferenteIstanzaId();

        ProtocolloResponse response;

        try {
            response = protocolloService.protocolla(request, groupId);

            if (Validator.isNotNull(response.getCodiceErrore())) {
                _log.error("Errore protocollazione. richiestaReferenteIstanzaId="
                                + richiestaReferenteIstanzaId
                                + ", codiceErrore="
                                + response.getCodiceErrore()
                                + ", descrizioneErrore="
                                + response.getDescrizioneErrore());

                rollbackGeneratedDocument(allegatoReferenteIstanzaId, documentRepositoryKeyId, groupId);

                _log.error(buildProtocolErrorMessage());
                throw new KosmosException();
            }

            richiestaReferenteIstanza.setDataProtocolloUscita(response.getDataProtocollo());
            richiestaReferenteIstanza.setNumeroProtocolloUscita(response.getNumeroProtocollo());
            richiestaReferenteIstanza.setNumeroProtocolloEstesoUscita(response.getNumeroProtocolloEsteso());

            richiestaReferenteIstanzaLocalService.updateRichiestaReferenteIstanza(richiestaReferenteIstanza);
        } catch (Exception e) {
            _log.error("Errore durante la protocollazione per richiestaReferenteIstanzaId=" + richiestaReferenteIstanzaId, e);

            rollbackGeneratedDocument(allegatoReferenteIstanzaId, documentRepositoryKeyId, groupId);

            _log.error(buildProtocolErrorMessage(), e);
            throw new KosmosException();
        }
    }

    private void rollbackGeneratedDocument(long allegatoReferenteIstanzaId, String documentRepositoryKeyId, long groupId) {
        Exception attachmentDeleteException = null;
        Exception documentDeleteException = null;

        try {
            allegatoReferenteIstanzaLocalService.deleteAllegatoReferenteIstanza(allegatoReferenteIstanzaId);
        } catch (Exception e) {
            attachmentDeleteException = e;
            _log.error("Errore durante il rollback del record allegato. allegatoReferenteIstanzaId=" + allegatoReferenteIstanzaId, e);
        }

        try {
            fileServiceFactory.getActiveFileService().deleteRequestFile(documentRepositoryKeyId, groupId);
        } catch (Exception e) {
            documentDeleteException = e;
            _log.error(
                    "Errore durante il rollback del documento repository. "
                            + "documentRepositoryKeyId="
                            + documentRepositoryKeyId
                            + ", groupId="
                            + groupId,
                    e);
        }

        if (attachmentDeleteException == null && documentDeleteException == null) {
            _log.info(
                    "Rollback completato. allegatoReferenteIstanzaId="
                            + allegatoReferenteIstanzaId
                            + ", documentRepositoryKeyId="
                            + documentRepositoryKeyId);
        }
    }

    private String buildProtocolErrorMessage() {
        return "Si è verificato un errore durante la protocollazione del documento.\n"
                + "Se l'errore persiste contattare l'assistenza.";
    }
