    private static final Log log = LogFactoryUtil.getLog(ProtocollazioneIntegrazioniService.class);

    @Override
    public RichiestaIntegrazione protocollaIstanzaForm(ServizioEnte servizioEnte, Richiesta richiesta, IstanzaForm istanzaForm) throws Exception {
        AllegatoRichiesta allegatoPrincipale = allegatoRichiestaLocalService.getAllegatiIntegrativi(istanzaForm.getIstanzaFormId(), true).get(0);
        List<AllegatoRichiesta> allegatiSecondari = allegatoRichiestaLocalService.getAllegatiIntegrativi(istanzaForm.getIstanzaFormId(), false);
        MessageUtility messageUtil = new MessageUtility(REST_BUNDLE_SYMBOLIC_NAME, null);


        List<Documento> allegatiProtocollazione = new ArrayList<>();
        for (AllegatoRichiesta allegato : allegatiSecondari) {
            allegatiProtocollazione.add(getDocumentoProtocollo(allegato));
        }

        Servizio servizio = servizioLocalService.getServizio(servizioEnte.getServizioId());

        IndirizzoTelematico indirizzoTelematico = new IndirizzoTelematico();
        indirizzoTelematico.setValore(richiesta.getEmail());

        Origine origine = new Origine();
        origine.setIndirizzoTelematico(indirizzoTelematico);

        Persona persona = new Persona();
        TipoPersona tipoPersona = TipoPersona.FISICA;
        if (Validator.isNotNull(richiesta.getPartitaIva())) {
            tipoPersona = TipoPersona.GIURIDICA;
            persona.setPartitaIva(richiesta.getPartitaIva());
        }

        persona.setTipoPersona(tipoPersona);

        persona.setCodiceFiscale(richiesta.getCodiceFiscale());
        persona.setDenominazione(richiesta.getUserName());

        Mittente mittente = new Mittente();
        mittente.setPersona(persona);
        origine.setMittente(mittente);

        ProtocolloRequest request = new ProtocolloRequest();

        String codiceIstanzaPortale = servizio.getCodice() + "/" + richiesta.getRichiestaId() + "/" + istanzaForm.getIstanzaFormId() + "/i";

        request.setCodiceIstanzaPortale(codiceIstanzaPortale);
        request.setTipoIstanzaPortale(TipoIstanzaPortaleServizi.SERVIZI_ISTANZA_INTEGRATIVA.name());

        if(Validator.isNotNull(servizioEnte.getTipoDocumento())){
            request.setTipoDocumento(servizioEnte.getTipoDocumento());
        }

        if(Validator.isNotNull(servizioEnte.getMittenteInterno())){
            request.setMittenteInterno(servizioEnte.getMittenteInterno());
        }

        if(Validator.isNotNull(servizioEnte.getIdPratica())){
            request.setIdPratica(servizioEnte.getIdPratica());
        }

        if(Validator.isNotNull(servizioEnte.getInCaricoA())){
            request.setInCaricoA(servizioEnte.getInCaricoA());
        }

        if(Validator.isNotNull(servizioEnte.getClassifica())){
            request.setClassifica(servizioEnte.getClassifica());
        }

        if(Validator.isNotNull(servizioEnte.getTipoProtocolloClient())){
            request.setTipoProtocolloClient(servizioEnte.getTipoProtocolloClient());
        }

        request.setDocumento(getDocumentoProtocollo(allegatoPrincipale));
        request.setAllegati(allegatiProtocollazione);
        request.setOggetto(richiesta.getOggetto());
        request.setOrigine(origine);

        if(Validator.isNotNull(servizioEnte.getAooProtocollo())) {
            request.setCodiceAOO(servizioEnte.getAooProtocollo());
        }

        if(Validator.isNotNull(servizioEnte.getUoProtocollo())) {
            request.setCodiceUO(servizioEnte.getUoProtocollo());
        }

        it.servizidigitali.protocollo.integration.model.ProtocolloResponse response = protocolloService.protocolla(request, istanzaForm.getGroupId());

        if (response == null) {
            String message = messageUtil.getMessage("setProtocolloInternalServerErrorException", String.valueOf(richiesta.getRichiestaId()));
            throw new InternalServerErrorException(message);
        }

        if (response.getCodiceErrore() != null) {
            String message = messageUtil.getMessage("setProtocolloInternalServerErrorException", String.valueOf(richiesta.getRichiestaId()), response.getDescrizioneErrore());
            throw new InternalServerErrorException(message);
        }

        RichiestaIntegrazione richiestaIntegrazione = richiestaIntegrazioneLocalService.createRichiestaIntegrazione(istanzaForm.getIstanzaFormId());

        if(Validator.isNotNull(response)) {
            if(Validator.isNotNull(response.getDataProtocollo())) {
                richiestaIntegrazione.setDataProtocollo(response.getDataProtocollo());
            }

            if(Validator.isNotNull(response.getNumeroProtocollo())) {
                richiestaIntegrazione.setNumeroProtocollo(response.getNumeroProtocollo());
            }

            if(Validator.isNotNull(response.getNumeroProtocolloEsteso())) {
                richiestaIntegrazione.setNumeroProtocolloEsteso(response.getNumeroProtocolloEsteso());
            }
        }

        // TODO: Capire invio pec notifica protocollazione
		/*InviaMailRequest inviaMailRequest = new InviaMailRequest();
		inviaMailRequest.setCodiceAOO(servizioEnte.getAooProtocollo());
		inviaMailRequest.setNumeroProtocollo(response.getNumeroProtocollo());

		LocalDate localDate = response.getDataProtocollo().toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
		int year = localDate.getYear();
		inviaMailRequest.setAnnoProtocollo(String.valueOf(year));
		inviaMailRequest.setMittenteMail(servizioEnte.getPecNotificaProtocollazione());
		String[] destinatari = new String[1];

		List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoList = domandaBandoDatoAggiuntivoLocalService.
