        request.setTipoProtocolloClient(servizioEnte.getTipoProtocolloClient());
    }

    List<AllegatoRichiesta> allegatiRichiesta = allegatoRichiestaLocalService.getAllegatiRichiestaByRichiestaId(richiesta.getRichiestaId());
