    request.setDocumento(getDocumentoProtocolloEsitoDomanda(richiesta, procedura.getTipoGenerazionePDFEsito(), richiesta.getGroupId(), userIdOperatore, portalURL, servizio.getCodice(), codiceOtpFirma, password, contesto, statoRichiesta));
