        request.setCodiceUO(servizioEnte.getUoProtocollo());
    }

    it.servizidigitali.protocollo.integration.model.ProtocolloResponse response = protocolloService.protocolla(request, richiesta.getGroupId());

    if (response == null) {
        String message = messageUtil.getMessage("setProtocolloInternalServerErrorException", String.valueOf(richiesta.getRichiestaId()));
        throw new InternalServerErrorException(message);
    }

    if (response.getCodiceErrore() != null) {
        String message = messageUtil.getMessage("setProtocolloInternalServerErrorException", String.valueOf(richiesta.getRichiestaId()), response.getDescrizioneErrore());
        throw new InternalServerErrorException(message);
    }

    richiesta.setNumeroProtocolloUscita(response.getNumeroProtocollo());

