private Documento getDocumentoProtocolloEsitoDomanda(Richiesta richiesta, String tipoGenerazionePdfEsitoDomanda, long groupId, long userId, String portalURL, String codiceServizio,
                                                     String codiceOtpFirma, String password, Contesto contesto, StatoRichiesta statoRichiesta) throws FirmaDigitaleRemotaException {
    TipoGenerazionePDF tipoGenerazionePDF = TipoGenerazionePDF.valueOf(tipoGenerazionePdfEsitoDomanda);
    PdfIstruttoriaService pdfService = pdfIstruttoriaServiceFactory.getPDFService(tipoGenerazionePDF);
    Procedura procedura = proceduraLocalService.fetchProcedura(richiesta.getProceduraId());
    byte[] pdfFirmato = pdfService.generaPDFEsitoDomanda(richiesta, CodiceTemplatePdf.ESITO_DOMANDA.name(), portalURL, statoRichiesta, userId);
    pdfFirmato = pdfServiceUtil.generaPDFArchive(pdfFirmato);

    if(Validator.isNotNull(codiceOtpFirma) && Validator.isNotNull(password)){
        try {
            pdfFirmato = firmaRemotaService.applicaSigillo(groupId, userId, contesto, pdfFirmato, codiceOtpFirma, password);
        } catch (FirmaDigitaleRemotaException e) {
            throw new FirmaDigitaleRemotaException();
        }

        if(Validator.isNull(pdfFirmato)){
            throw new FirmaDigitaleRemotaException();
        }
    }

    try {
        pdfFirmato = firmaRemotaService.applicaSigillo(groupId, 0, contesto, pdfFirmato, null, null);
    } catch (FirmaDigitaleRemotaException e) {
        throw new FirmaDigitaleRemotaException();
    }

    if(Validator.isNull(pdfFirmato)){
        throw new FirmaDigitaleRemotaException();
    }


    if(Validator.isNotNull(pdfFirmato)){
        String descrizione = "Esito chiusura richiesta '" + procedura.getNome() + "' - ID: " + richiesta.getUserId();
        salvaAllegato(pdfFirmato, richiesta.getRichiestaId(), richiesta.getOggetto(), codiceServizio, "esito-richiesta-" + richiesta.getRichiestaId() + ".pdf", descrizione, userId, groupId);
    }


    Documento documento = new Documento();
    documento.setContenuto(pdfFirmato);
    documento.setNome("Richiesta integrazione ID " + richiesta.getRichiestaId() + ".pdf" );
    documento.setOggetto("Richiesta integrazione ID " + richiesta.getRichiestaId());
    documento.setTipo(null);
    documento.setTipoMIME(null);
    documento.setTitolo("Richiesta integrazione ID " + richiesta.getRichiestaId());

    return documento;
}

