271												+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
272										salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_ESECUZIONE_DESCRIZIONE, compilaDocumentoVolontario, contesto);
273									}
274									else if  (compilaDocumentoVolontario) {
275										nomeFile = ALLEGATO_DOMANDA_VOLONTARIA_PREFIX
276												+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
277										salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_VOLONTARIA_DESCRIZIONE, compilaDocumentoVolontario, contesto);
278									}
279									else {
280										nomeFile = ALLEGATO_DOMANDA_INTEGRAZIONE_PREFIX
281												+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
282										salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_INTEGRAZIONE_DESCRIZIONE, compilaDocumentoVolontario, contesto);
283									}
284								} catch (DataAccessException e) {
285									throw new DataAccessException("Errore durante il salvataggio del documento PDF dell'integrazione", e);
286								} catch (Exception e) {
287									log.error("errore generazione documento pdf", e);
288									throw new DataAccessException("Errore durante la generazione del documento PDF dell'integrazione", e);
289								}
290							}
291						}
292					}
293				}
294	
295				aggiornaStatoIstanza(istanzaDomandaBando, isQuestionario);
296	
297				if (isQuestionario) {
298					String indietroUrl = presentatoreFormFrontendService.componiIndietroQuestionarioUrl(domandaBando);
299	
300					if (Validator.isNotNull(indietroUrl)) {
301						response.sendRedirect(indietroUrl);
302					}
303	
304					List<AttivitaDomandaBando> attivitaList = attivitaDomandaBandoLocalService
305							.getAttivitaDomandaBandoByDomandaBandoId(domandaBando.getDomandaBandoId());
306	
307					if(ListUtil.isNotNull(attivitaList) && ListUtil.isNotEmpty(attivitaList)) {
308						for (AttivitaDomandaBando attivita: attivitaList) {
309							StatoDomandaBandoEnum statoDomandaBandoEnum = StatoDomandaBandoEnum.findByName(attivita.getStato());
310							if (Validator.isNotNull(statoDomandaBandoEnum) && statoDomandaBandoEnum.equals(StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA)) {
311								String note = attivita.getNote();
312								if (Validator.isNull(note)) {
313									attivita.setNote(PresentatoreFormsPortletKeys.QUESTIONARIO_COMPILATO);
314									attivitaDomandaBandoLocalService.updateAttivitaDomandaBando(attivita);
315								}
316							}
317						}
318					}
319				}
320	
321				if (compilaDocumentoEsecuzione) {
322					renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_DOCUMENTI_ESECUZIONE_RENDER_COMMAND);
323					renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
324				} else if (compilaDocumentoVolontario) {
325					renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_FORM_INTEGRATIVI_VOLONTARI_RENDER_COMMAND);
326					renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
327				} else {
328					renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_FORM_INTEGRATIVI_RENDER_COMMAND);
329					renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
330				}
331			} catch (UserMismatchException | WrongStateException e) {
332				auditService.saveErrorLog(request, e.getMessage());
333				log.error(e);
334				SessionErrors.add(request, e.getClass());
335				renderParameters.setValue("mvcPath", PresentatoreFormsPortletKeys.JSP_ERROR);
336			} catch (FirmeNonValideException e) {
337				auditService.saveErrorLog(request, e.getMessage());
338				log.error("verifica firma digitale disciplinare per domanda bando " + domandaBando.getDomandaBandoId()
339						+ " fallita :: " + e.getMessage(), e);
340	
341				request.setAttribute("erroreDocumentoPrincipale", e.getErroreDocumentoPrincipale());
342				request.setAttribute("erroriAllegati", e.getErroriAllegati());
343	
344				renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.CARICA_ISTANZA_INTEGRATIVA_RENDER_COMMAND);
345				renderParameters.setValue(PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID,
346						String.valueOf(istanzaDomandaBandoId));
347			} catch (FirmaDigitaleRemotaException e) {
348				auditService.saveErrorLog(request, e.getMessage());
349				log.error(e);
350				SessionErrors.add(request, e.getClass());
351				renderParameters.setValue("mvcPath", PresentatoreFormsPortletKeys.JSP_ERROR);
352			} catch (KosmosException e) {
353				auditService.saveErrorLog(request, e.getMessage());
354				log.error(e);
355				SessionErrors.add(request, e.getClass());
356				renderParameters.setValue("mvcPath", PresentatoreFormsPortletKeys.JSP_ERROR);
357			} catch (DataAccessException e) {
358				auditService.saveErrorLog(request, e.getMessage());
359				log.error(e);
360				SessionErrors.add(request, e.getClass());
361				renderParameters.setValue("mvcPath", PresentatoreFormsPortletKeys.JSP_ERROR);
362			} catch (Exception e) {
363				auditService.saveErrorLog(request, e.getMessage());
364				log.error(e);
365				SessionErrors.add(request, PresentatoreFormsPortletKeys.ERRORE_GENERICO);
366				renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.CARICA_ISTANZA_INTEGRATIVA_RENDER_COMMAND);
367				renderParameters.setValue(PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID,
368						String.valueOf(istanzaDomandaBandoId));
369			}
370		}
