372		private void salvaDocumentoPdf(ActionRequest request, String nomeFile, String descrizione, boolean compilaDocumentoVolontario, Contesto contesto)
373				throws PDFServiceException, PortalException {
374			long istanzaDomandaBandoId = ParamUtil.getLong(request, PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID);
375			ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);
376			User user = themeDisplay.getUser();
377			IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService
378					.getIstanzaDomandaBando(istanzaDomandaBandoId);
379			DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
380			Bando bando = bandoLocalService.getBando(domandaBando.getBandoId());
381			byte[] content = null;
382	
383			Form form = presentatoreFormFrontendService.getFormAndDefinizioneAllegati(istanzaDomandaBando.getFormId());
384	
385			FormData formData = AlpacaUtil.loadFormData(form, istanzaDomandaBando.getJson(), true,
386					themeDisplay.getPortalURL());
387			AlpacaJsonStructure alpacaStructure = formData.getAlpaca();
388	
389			Gson gson = new Gson();
390			JsonParser jsonParser = new JsonParser();
391			alpacaStructure.setSchema(AlpacaUtil.addAttachmentsToSchema(gson.toJson(alpacaStructure.getSchema()),
392					form.getListaDefinizioneAllegato()));
393			alpacaStructure.setOptions(AlpacaUtil.loadOptions(gson.toJson(alpacaStructure.getOptions()),
394					form.getListaDefinizioneAllegato(), true, themeDisplay.getPortalURL()));
395			alpacaStructure.setData(jsonParser.parse(gson.toJson(alpacaStructure.getData())).getAsJsonObject());
396	
397			PDFService pdfService = pdfServiceFactory.getPDFService(TipoGenerazionePDF.NATIVA);
398			content = pdfService.generaPDFIntegrazioni(themeDisplay.getUser().getScreenName(), alpacaStructure,
399					domandaBando, "", istanzaDomandaBandoId);
400	
401			if(Validator.isNotNull(content) && compilaDocumentoVolontario){
402				content = pdfServiceUtil.generaPDFArchive(content);
403				if (bando.isSigilloQualificato()) {
404	                content = firmaRemotaService.applicaSigillo(themeDisplay.getScopeGroupId(), 0, contesto, content, null, null);
405				}
406			}
407	
408			List<AllegatoDomandaBando> allegatiDomandaBando = allegatoDomandaBandoLocalService
409					.getListaAllegatiByIstanzaIdAndDefAllegatoId(istanzaDomandaBando.getIstanzaDomandaBandoId(), 0);
410	
411			AllegatoDomandaBando allegatoDomandaBando = null;
412			if (Validator.isNotNull(allegatiDomandaBando) && !allegatiDomandaBando.isEmpty()) {
413				allegatoDomandaBando = allegatiDomandaBando.get(0);
414			}
415			InputStream stream = new ByteArrayInputStream(content);
416			String mimeType = MimeTypesUtil.getContentType(stream, nomeFile);
417			FileService activeFileService = fileServiceFactory.getActiveFileService();
418			String impronta = "";
419			VerificaResponse dettagliAllegato = allegatoDomandaBandoService.recuperaDettagliAllegato(themeDisplay.getScopeGroupId(), content, contesto);
420	
421			if (Validator.isNotNull(dettagliAllegato) && Validator.isNotNull(dettagliAllegato.getImpronta())) {
422				impronta = dettagliAllegato.getImpronta();
423			}
424	
425			String idDocumentale = addOrUpdatePdf(themeDisplay, user, domandaBando, bando, stream, nomeFile,
426					descrizione, mimeType, activeFileService, allegatoDomandaBando);
427	
428			addOrUpdateAllegato(themeDisplay, user, istanzaDomandaBando, domandaBando, nomeFile, descrizione,
429					allegatoDomandaBando, idDocumentale, impronta);
430		}
431	
432		private void addOrUpdateAllegato(ThemeDisplay themeDisplay, User user, IstanzaDomandaBando istanzaDomandaBando,
433				DomandaBando domandaBando, String nomeFile, String descrizione, AllegatoDomandaBando allegatoDomandaBando,
434				String idDocumentale, String impronta) {
435			if (allegatoDomandaBando != null) {
436				allegatoDomandaBando.setIdDocumentale(idDocumentale);
437			} else {
438				long allegatoDomandaBandoId = counterLocalService.increment();
439				allegatoDomandaBando = allegatoDomandaBandoLocalService.createAllegatoDomandaBando(allegatoDomandaBandoId);
440				allegatoDomandaBando.setGroupId(themeDisplay.getSiteGroupId());
441				allegatoDomandaBando.setCompanyId(themeDisplay.getCompanyId());
442				allegatoDomandaBando.setUserId(user.getUserId());
443				allegatoDomandaBando.setUserName(user.getFullName());
444				allegatoDomandaBando.setDomandaBandoId(domandaBando.getDomandaBandoId());
445				allegatoDomandaBando.setIdDocumentale(idDocumentale);
446				allegatoDomandaBando.setDefinizioneAllegatoId(0);
447				allegatoDomandaBando.setPrincipale(false);
448				allegatoDomandaBando.setNome(nomeFile);
449				allegatoDomandaBando.setTitolo(nomeFile);
450				allegatoDomandaBando.setDescrizione(descrizione);
451				allegatoDomandaBando.setVisibile(true);
452				allegatoDomandaBando.setImpronta(impronta);
453				allegatoDomandaBando.setIstanzaDomandaBandoId(istanzaDomandaBando.getIstanzaDomandaBandoId());
454			}
455	
456			allegatoDomandaBandoLocalService.updateAllegatoDomandaBando(allegatoDomandaBando);
457		}
458	
459		private String addOrUpdatePdf(ThemeDisplay themeDisplay, User user, DomandaBando domandaBando, Bando bando,
460				InputStream stream, String nomeFile, String descrizione, String mimeType, FileService activeFileService,
461				AllegatoDomandaBando allegatoRichiesta) {
462			if (allegatoRichiesta != null) {
463				activeFileService.deleteRequestFile(allegatoRichiesta.getIdDocumentale(), allegatoRichiesta.getGroupId());
464			}
465	
466			it.servizidigitali.file.utility.model.File idDocumentale = activeFileService.saveRequestFile(nomeFile, nomeFile,
467					descrizione, bando.getCodice(), domandaBando.getDomandaBandoId(), stream, mimeType, user.getUserId(),
468					themeDisplay.getSiteGroupId());
469			return idDocumentale.getId();
470		}
471	
472		private void aggiornaStatoIstanza(IstanzaDomandaBando istanzaDomandaBando, boolean isQuestionario) {
473	
474			if (isQuestionario) {
475				istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.CONFERMATA.name());
476			} else {
477				String statoCorrente = istanzaDomandaBando.getStato();
478				if (StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA.name().equals(statoCorrente)
479						|| StatoIntegrazioneDomandaBandoEnum.BOZZA.name().equals(statoCorrente)) {
480					istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.VALIDATA.name());
481				}
482			}
483	
484			istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);
485		}
486	
487		private void checkStatoRichiesta(ThemeDisplay themeDisplay, DomandaBando domandaBando)
488				throws UserMismatchException, WrongStateException, PortalException {
489			if (domandaBando.getUserId() != themeDisplay.getUserId()) {
490				throw new UserMismatchException();
491			}
492	
493			if (!StatoDomandaBandoEnum.ATTESA_INTEGRAZIONI.name().equals(domandaBando.getStato())
494					&& !StatoDomandaBandoEnum.ATTESA_BROCHURE.name().equals(domandaBando.getStato())
495					&& !StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA.name().equals(domandaBando.getStato())) {
496				throw new WrongStateException();
497			}
498		}
499	
500		private String getFirmatarioDocumento(VerificaResponse controlloFirma){
501			String firmatari = "";
502	
503			if(Validator.isNotNull(controlloFirma)){
504				Set<String> firmatariSet = controlloFirma.getFirmatari();
505	
506				if(Validator.isNotNull(firmatariSet) && !firmatariSet.isEmpty()){
507					firmatari = String.join(",", firmatariSet);
508				}
509			}
510	
511			return firmatari;
512		}
513	
514	}

