@Component(immediate = true, service = MVCActionCommand.class, property = {
		"javax.portlet.name=" + PresentatoreFormsPortletKeys.PRESENTATOREFORMS,
		"mvc.command.name=" + PresentatoreFormsPortletKeys.INVIA_FORM_INTEGRATIVO_ACTION_COMMAND })
public class InviaFormIntegrativoActionCommand extends BaseMVCActionCommand {

	private final static Log log = LogFactoryUtil.getLog(InviaFormIntegrativoActionCommand.class);
	private static final SimpleDateFormat formatter = new SimpleDateFormat("dd-MM-yyyy-HH-mm-ss");
	private final static String ALLEGATO_DOMANDA_INTEGRAZIONE_PREFIX = "allegato-domanda-esecuzione-";
	private final static String ALLEGATO_DOMANDA_ESECUZIONE_PREFIX = "allegato-domanda-integrazione-";
	private final static String ALLEGATO_DOMANDA_VOLONTARIA_PREFIX = "allegato-domanda-";
	private final static String ALLEGATO_DOMANDA_INTEGRAZIONE_DESCRIZIONE = " Allegato Domanda Integrazione";
	private final static String ALLEGATO_DOMANDA_ESECUZIONE_DESCRIZIONE = "Allegato Domanda Esecuzione";
	private final static String ALLEGATO_DOMANDA_VOLONTARIA_DESCRIZIONE = "Allegato Domanda";
	@Reference
	private AllegatoDomandaBandoService allegatoDomandaBandoService;

	@Reference
	private PDFServiceFactory pdfServiceFactory;

	@Reference
	private PresentatoreFormFrontendService presentatoreFormFrontendService;

	@Reference
	private FileServiceFactory fileServiceFactory;

	@Reference
	private CounterLocalService counterLocalService;

	@Reference
	private IstanzaDomandaBandoLocalService istanzaDomandaBandoLocalService;

	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;

	@Reference
	private StatoDomandaLocalService statoDomandaLocalService;

	@Reference
	private BandoLocalService bandoLocalService;

	@Reference
	private AllegatoDomandaBandoLocalService allegatoDomandaBandoLocalService;

	@Reference
	private AuditService auditService;

	@Reference
	private FormLocalService formLocalService;

	@Reference
	private FirmaRemotaService firmaRemotaService;

	@Reference
	private PdfService pdfServiceUtil;

	@Reference
	private AttivitaDomandaBandoLocalService attivitaDomandaBandoLocalService;

	@Override
	protected void doProcessAction(ActionRequest request, ActionResponse response) throws Exception {
		MutableRenderParameters renderParameters = response.getRenderParameters();
		long istanzaDomandaBandoId = ParamUtil.getLong(request, PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID);
		DomandaBando domandaBando = null;
		Form form = null;
		boolean firmaDigitaleDocumentoAbilitata = false;
		List<TipoFirmaDigitale> listaFormatiFirma = null;

		try {
			ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);
			User user = themeDisplay.getUser();
			ResourceBundleLoader resourceBundleLoader = ResourceBundleLoaderUtil.getResourceBundleLoaderByBundleSymbolicName(PresentatoreFormsPortletKeys.BUNDLE_SYMBOLIC_NAME);

			UploadPortletRequest uploadPortletRequest = PortalUtil.getUploadPortletRequest(request);

			boolean compilaDocumentoEsecuzione = ParamUtil.getBoolean(request, PresentatoreFormsPortletKeys.COMPILA_DOCUMENTO_ESECUZIONE);
			boolean compilaDocumentoVolontario = ParamUtil.getBoolean(request, PresentatoreFormsPortletKeys.COMPILA_DOCUMENTO_VOLONTARIO);
			IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService.getIstanzaDomandaBando(istanzaDomandaBandoId);
			domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
			Bando bando = bandoLocalService.getBando(domandaBando.getBandoId());
			Contesto contesto = Contesto.valueOf(bando.getContesto());
			boolean isQuestionario = presentatoreFormFrontendService.checkIsQuestionario(istanzaDomandaBando, bando);
			String nomeFile = "";

			if (!compilaDocumentoEsecuzione && !compilaDocumentoVolontario) {
				checkStatoRichiesta(themeDisplay, domandaBando);
			}

			String erroreFirmaDocumentoPrincipale = null;
			List<String> erroreFirmaAllegati = new ArrayList<>();

			if (istanzaDomandaBandoId > 0) {
				form = formLocalService.getForm(istanzaDomandaBando.getFormId());

				if (Validator.isNotNull(domandaBando)) {
					bando = bandoLocalService.fetchBando(domandaBando.getBandoId());

					if (Validator.isNotNull(bando) && bando.getBandoId() > 0) {
						boolean firmaDocumentoIntAbilitata = bando.getRichiestaFirmaIntegrazione();
						if (firmaDocumentoIntAbilitata) {
							listaFormatiFirma = TipoFirmaDigitale.parse(bando.getFormatiFirmaDigitale());
							firmaDigitaleDocumentoAbilitata = listaFormatiFirma != null && !listaFormatiFirma.isEmpty();
						}

						File fileFirmato = uploadPortletRequest.getFile("uploadFileFirmato");
						String impronta = "";
						String firmatario = "";
						boolean firmatoDigitalmente = false;
						if (firmaDocumentoIntAbilitata && firmaDigitaleDocumentoAbilitata) {
							// Caso firma digitale: verifica firma e salva allegato
							if (Validator.isNotNull(fileFirmato)) {
								byte[] allegatoBytes = Files.readAllBytes(fileFirmato.toPath());
								long definizioneAllegatoId = 0;
								String fullFileName = uploadPortletRequest.getFileName("uploadFileFirmato");
								String extension = FileUtil.getExtension(fullFileName);
								nomeFile = FileUtil.stripExtension(fullFileName);
								String timestamp = formatter.format(new Date());
								String titolo = "";

								if (compilaDocumentoEsecuzione) {
									titolo = String.format("allegato-esecuzione-%s-%s.%s", nomeFile, timestamp, extension);
								}
								else if (compilaDocumentoVolontario) {
									titolo = String.format("allegato-%s-%s.%s", nomeFile, timestamp, extension);
								}
								else {
									titolo = String.format("allegato-integrativo-%s-%s.%s", nomeFile, timestamp, extension);
								}
								try {
									VerificaResponse controlloFirma = allegatoDomandaBandoService.checkFirmaDigitaleDocumento(allegatoBytes,
											"Il documento", user.getScreenName(), listaFormatiFirma,
											bando.isSigilloQualificato(), bando.isVerificaFirmaCf(),
											themeDisplay.getScopeGroupId(), contesto);

									firmatario = getFirmatarioDocumento(controlloFirma);

									if(Validator.isNotNull(controlloFirma) && Validator.isNotNull(controlloFirma.getImpronta())){
										impronta = controlloFirma.getImpronta();
									}

									firmatoDigitalmente = true;
								} catch (PDFSignatureException e) {
									erroreFirmaDocumentoPrincipale = e.getMessage();
								}

								if (Validator.isNotNull(erroreFirmaDocumentoPrincipale)
										|| !erroreFirmaAllegati.isEmpty()) {
									throw new FirmeNonValideException(erroreFirmaDocumentoPrincipale,
											erroreFirmaAllegati);
								}

								AllegatoDomandaBando allegato = allegatoDomandaBandoService.salvaAllegatoRichiesta(
										allegatoBytes,impronta, titolo, titolo, bando, domandaBando.getDomandaBandoId(),
										definizioneAllegatoId, istanzaDomandaBando.getIstanzaDomandaBandoId(), firmatario, firmatoDigitalmente,
										user.getFullName(), user.getUserId(), themeDisplay.getSiteGroupId(),
										themeDisplay.getCompanyId(), null, null);
							}

						} else if (firmaDocumentoIntAbilitata && !firmaDigitaleDocumentoAbilitata) {
							// Caso firma olografa: verifica impronta e salva allegato
							if (Validator.isNotNull(fileFirmato)) {
								byte[] allegatoBytes = Files.readAllBytes(fileFirmato.toPath());

								String chiaveErrore = presentatoreFormFrontendService.verificaImprontaIstanza(
										domandaBando.getDomandaBandoId(),
										istanzaDomandaBando.getIstanzaDomandaBandoId(),
										allegatoBytes);
								if (Validator.isNotNull(chiaveErrore)) {
									erroreFirmaDocumentoPrincipale = resourceBundleLoader
											.loadResourceBundle(themeDisplay.getLocale()).getString(chiaveErrore);
									throw new FirmeNonValideException(erroreFirmaDocumentoPrincipale, erroreFirmaAllegati);
								}

								long definizioneAllegatoId = 0;
								String fullFileName = uploadPortletRequest.getFileName("uploadFileFirmato");
								String extension = FileUtil.getExtension(fullFileName);
								nomeFile = FileUtil.stripExtension(fullFileName);
								String timestamp = formatter.format(new Date());
								String titolo = "";

								if (compilaDocumentoEsecuzione) {
									titolo = String.format("allegato-esecuzione-%s-%s.%s", nomeFile, timestamp, extension);
								}
								else if (compilaDocumentoVolontario) {
									titolo = String.format("allegato-%s-%s.%s", nomeFile, timestamp, extension);
								}
								else {
									titolo = String.format("allegato-integrativo-%s-%s.%s", nomeFile, timestamp, extension);
								}

								AllegatoDomandaBando allegato = allegatoDomandaBandoService.salvaAllegatoRichiesta(
										allegatoBytes, impronta, titolo, titolo, bando, domandaBando.getDomandaBandoId(),
										definizioneAllegatoId, istanzaDomandaBando.getIstanzaDomandaBandoId(), firmatario, firmatoDigitalmente,
										user.getFullName(), user.getUserId(), themeDisplay.getSiteGroupId(),
										themeDisplay.getCompanyId(), null, null);
							}

						} else {
							if (!erroreFirmaAllegati.isEmpty()) {
								throw new FirmeNonValideException(erroreFirmaDocumentoPrincipale, erroreFirmaAllegati);
							}

							// Caso PDF generato internamente senza firma
							try {
								if (compilaDocumentoEsecuzione ) {
									nomeFile = ALLEGATO_DOMANDA_ESECUZIONE_PREFIX
											+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
									salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_ESECUZIONE_DESCRIZIONE, compilaDocumentoVolontario, contesto);
								}
								else if  (compilaDocumentoVolontario) {
									nomeFile = ALLEGATO_DOMANDA_VOLONTARIA_PREFIX
											+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
									salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_VOLONTARIA_DESCRIZIONE, compilaDocumentoVolontario, contesto);
								}
								else {
									nomeFile = ALLEGATO_DOMANDA_INTEGRAZIONE_PREFIX
											+ formatter.format(istanzaDomandaBando.getModifiedDate()) + ".pdf";
									salvaDocumentoPdf(request, nomeFile, ALLEGATO_DOMANDA_INTEGRAZIONE_DESCRIZIONE, compilaDocumentoVolontario, contesto);
								}
							} catch (DataAccessException e) {
								throw new DataAccessException("Errore durante il salvataggio del documento PDF dell'integrazione", e);
							} catch (Exception e) {
								log.error("errore generazione documento pdf", e);
								throw new DataAccessException("Errore durante la generazione del documento PDF dell'integrazione", e);
							}
						}
					}
				}
			}

			aggiornaStatoIstanza(istanzaDomandaBando, isQuestionario);

			if (isQuestionario) {
				String indietroUrl = presentatoreFormFrontendService.componiIndietroQuestionarioUrl(domandaBando);

				if (Validator.isNotNull(indietroUrl)) {
					response.sendRedirect(indietroUrl);
				}

				List<AttivitaDomandaBando> attivitaList = attivitaDomandaBandoLocalService
						.getAttivitaDomandaBandoByDomandaBandoId(domandaBando.getDomandaBandoId());

				if(ListUtil.isNotNull(attivitaList) && ListUtil.isNotEmpty(attivitaList)) {
					for (AttivitaDomandaBando attivita: attivitaList) {
						StatoDomandaBandoEnum statoDomandaBandoEnum = StatoDomandaBandoEnum.findByName(attivita.getStato());
						if (Validator.isNotNull(statoDomandaBandoEnum) && statoDomandaBandoEnum.equals(StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA)) {
							String note = attivita.getNote();
							if (Validator.isNull(note)) {
								attivita.setNote(PresentatoreFormsPortletKeys.QUESTIONARIO_COMPILATO);
								attivitaDomandaBandoLocalService.updateAttivitaDomandaBando(attivita);
							}
						}
					}
				}
			}

			if (compilaDocumentoEsecuzione) {
				renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_DOCUMENTI_ESECUZIONE_RENDER_COMMAND);
				renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
			} else if (compilaDocumentoVolontario) {
				renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_FORM_INTEGRATIVI_VOLONTARI_RENDER_COMMAND);
				renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
			} else {
				renderParameters.setValue("mvcRenderCommandName", PresentatoreFormsPortletKeys.LISTA_FORM_INTEGRATIVI_RENDER_COMMAND);
				renderParameters.setValue(PresentatoreFormsPortletKeys.DOMANDABANDO_ID, String.valueOf(domandaBando.getDomandaBandoId()));
			}
		} catch (UserMismatchException | WrongStateException e) {
