	private void salvaDocumentoPdf(ActionRequest request, String nomeFile, String descrizione, boolean compilaDocumentoVolontario, Contesto contesto)
			throws PDFServiceException, PortalException {
		long istanzaDomandaBandoId = ParamUtil.getLong(request, PresentatoreFormsPortletKeys.ISTANZA_DOMANDABANDO_ID);
		ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);
		User user = themeDisplay.getUser();
		IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService
				.getIstanzaDomandaBando(istanzaDomandaBandoId);
		DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(istanzaDomandaBando.getDomandaBandoId());
		Bando bando = bandoLocalService.getBando(domandaBando.getBandoId());
		byte[] content = null;

		Form form = presentatoreFormFrontendService.getFormAndDefinizioneAllegati(istanzaDomandaBando.getFormId());

		FormData formData = AlpacaUtil.loadFormData(form, istanzaDomandaBando.getJson(), true,
				themeDisplay.getPortalURL());
		AlpacaJsonStructure alpacaStructure = formData.getAlpaca();

		Gson gson = new Gson();
		JsonParser jsonParser = new JsonParser();
		alpacaStructure.setSchema(AlpacaUtil.addAttachmentsToSchema(gson.toJson(alpacaStructure.getSchema()),
				form.getListaDefinizioneAllegato()));
		alpacaStructure.setOptions(AlpacaUtil.loadOptions(gson.toJson(alpacaStructure.getOptions()),
				form.getListaDefinizioneAllegato(), true, themeDisplay.getPortalURL()));
		alpacaStructure.setData(jsonParser.parse(gson.toJson(alpacaStructure.getData())).getAsJsonObject());

		PDFService pdfService = pdfServiceFactory.getPDFService(TipoGenerazionePDF.NATIVA);
		content = pdfService.generaPDFIntegrazioni(themeDisplay.getUser().getScreenName(), alpacaStructure,
				domandaBando, "", istanzaDomandaBandoId);

		if(Validator.isNotNull(content) && compilaDocumentoVolontario){
			content = pdfServiceUtil.generaPDFArchive(content);
			if (bando.isSigilloQualificato()) {
                content = firmaRemotaService.applicaSigillo(themeDisplay.getScopeGroupId(), 0, contesto, content, null, null);
			}
		}

		List<AllegatoDomandaBando> allegatiDomandaBando = allegatoDomandaBandoLocalService
				.getListaAllegatiByIstanzaIdAndDefAllegatoId(istanzaDomandaBando.getIstanzaDomandaBandoId(), 0);

		AllegatoDomandaBando allegatoDomandaBando = null;
		if (Validator.isNotNull(allegatiDomandaBando) && !allegatiDomandaBando.isEmpty()) {
			allegatoDomandaBando = allegatiDomandaBando.get(0);
		}
		InputStream stream = new ByteArrayInputStream(content);
		String mimeType = MimeTypesUtil.getContentType(stream, nomeFile);
		FileService activeFileService = fileServiceFactory.getActiveFileService();
		String impronta = "";
		VerificaResponse dettagliAllegato = allegatoDomandaBandoService.recuperaDettagliAllegato(themeDisplay.getScopeGroupId(), content, contesto);

		if (Validator.isNotNull(dettagliAllegato) && Validator.isNotNull(dettagliAllegato.getImpronta())) {
			impronta = dettagliAllegato.getImpronta();
		}

		String idDocumentale = addOrUpdatePdf(themeDisplay, user, domandaBando, bando, stream, nomeFile,
				descrizione, mimeType, activeFileService, allegatoDomandaBando);

		addOrUpdateAllegato(themeDisplay, user, istanzaDomandaBando, domandaBando, nomeFile, descrizione,
				allegatoDomandaBando, idDocumentale, impronta);
	}

	private void addOrUpdateAllegato(ThemeDisplay themeDisplay, User user, IstanzaDomandaBando istanzaDomandaBando,
			DomandaBando domandaBando, String nomeFile, String descrizione, AllegatoDomandaBando allegatoDomandaBando,
			String idDocumentale, String impronta) {
		if (allegatoDomandaBando != null) {
			allegatoDomandaBando.setIdDocumentale(idDocumentale);
		} else {
			long allegatoDomandaBandoId = counterLocalService.increment();
			allegatoDomandaBando = allegatoDomandaBandoLocalService.createAllegatoDomandaBando(allegatoDomandaBandoId);
			allegatoDomandaBando.setGroupId(themeDisplay.getSiteGroupId());
			allegatoDomandaBando.setCompanyId(themeDisplay.getCompanyId());
			allegatoDomandaBando.setUserId(user.getUserId());
			allegatoDomandaBando.setUserName(user.getFullName());
			allegatoDomandaBando.setDomandaBandoId(domandaBando.getDomandaBandoId());
			allegatoDomandaBando.setIdDocumentale(idDocumentale);
			allegatoDomandaBando.setDefinizioneAllegatoId(0);
			allegatoDomandaBando.setPrincipale(false);
			allegatoDomandaBando.setNome(nomeFile);
			allegatoDomandaBando.setTitolo(nomeFile);
			allegatoDomandaBando.setDescrizione(descrizione);
			allegatoDomandaBando.setVisibile(true);
			allegatoDomandaBando.setImpronta(impronta);
			allegatoDomandaBando.setIstanzaDomandaBandoId(istanzaDomandaBando.getIstanzaDomandaBandoId());
		}

		allegatoDomandaBandoLocalService.updateAllegatoDomandaBando(allegatoDomandaBando);
	}

	private String addOrUpdatePdf(ThemeDisplay themeDisplay, User user, DomandaBando domandaBando, Bando bando,
			InputStream stream, String nomeFile, String descrizione, String mimeType, FileService activeFileService,
			AllegatoDomandaBando allegatoRichiesta) {
		if (allegatoRichiesta != null) {
			activeFileService.deleteRequestFile(allegatoRichiesta.getIdDocumentale(), allegatoRichiesta.getGroupId());
		}

		it.servizidigitali.file.utility.model.File idDocumentale = activeFileService.saveRequestFile(nomeFile, nomeFile,
				descrizione, bando.getCodice(), domandaBando.getDomandaBandoId(), stream, mimeType, user.getUserId(),
				themeDisplay.getSiteGroupId());
		return idDocumentale.getId();
	}

	private void aggiornaStatoIstanza(IstanzaDomandaBando istanzaDomandaBando, boolean isQuestionario) {

		if (isQuestionario) {
			istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.CONFERMATA.name());
		} else {
			String statoCorrente = istanzaDomandaBando.getStato();
			if (StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA.name().equals(statoCorrente)
					|| StatoIntegrazioneDomandaBandoEnum.BOZZA.name().equals(statoCorrente)) {
				istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.VALIDATA.name());
			}
		}

		istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);
	}

	private void checkStatoRichiesta(ThemeDisplay themeDisplay, DomandaBando domandaBando)
			throws UserMismatchException, WrongStateException, PortalException {
		if (domandaBando.getUserId() != themeDisplay.getUserId()) {
			throw new UserMismatchException();
		}

		if (!StatoDomandaBandoEnum.ATTESA_INTEGRAZIONI.name().equals(domandaBando.getStato())
				&& !StatoDomandaBandoEnum.ATTESA_BROCHURE.name().equals(domandaBando.getStato())
				&& !StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA.name().equals(domandaBando.getStato())) {
			throw new WrongStateException();
		}
	}

	private String getFirmatarioDocumento(VerificaResponse controlloFirma){
		String firmatari = "";

		if(Validator.isNotNull(controlloFirma)){
			Set<String> firmatariSet = controlloFirma.getFirmatari();

			if(Validator.isNotNull(firmatariSet) && !firmatariSet.isEmpty()){
				firmatari = String.join(",", firmatariSet);
			}
		}

		return firmatari;
	}

