package it.servizidigitali.common.fdr.dto;

import java.util.Set;

public class VerificaResponse {
    private String impronta;
    private boolean firmato;
    private boolean firmaValida;
    private Set<String> firme;
    private Set<String> firmatari;
    private String tipoFirma;
    private boolean sigilloQualificato;

    public String getImpronta() {
        return impronta;
    }

    public void setImpronta(String impronta) {
        this.impronta = impronta;
    }

    public boolean isFirmato() {
        return firmato;
    }

    public void setFirmato(boolean firmato) {
        this.firmato = firmato;
    }

    public boolean isFirmaValida() {
        return firmaValida;
    }

    public void setFirmaValida(boolean firmaValida) {
        this.firmaValida = firmaValida;
    }

    public Set<String> getFirme() {
        return firme;
    }

    public void setFirme(Set<String> firme) {
        this.firme = firme;
    }

    public Set<String> getFirmatari() {
        return firmatari;
    }

    public void setFirmatari(Set<String> firmatari) {
        this.firmatari = firmatari;
    }

    public String getTipoFirma() {
        return tipoFirma;
    }

    public void setTipoFirma(String tipoFirma) {
        this.tipoFirma = tipoFirma;
    }

    public boolean isSigilloQualificato() {
        return sigilloQualificato;
    }

    public void setSigilloQualificato(boolean sigilloQualificato) {
        this.sigilloQualificato = sigilloQualificato;
    }
}
